using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.Json;
using Deception.Core;
using Deception.PolyModAdapter;
namespace Deception.Tests
{
 public static class CombatPreviewTests
 {
  static int Assertions;static readonly List<string> Tests=new();
  static void Check(bool v,string why){Assertions++;if(!v)throw new Exception(why);}
  static void Test(string id,Action a){try{a();Tests.Add(id);}catch(Exception e){throw new Exception(id,e);}}
  static LedgerAppearance Appearance(string form="defender",ushort hp=150,ushort max=150,bool veteran=false,string[]? effects=null,LedgerAppearance? cargo=null)=>new(form,new("imperius","default"),new("imperius","default"),new("imperius","default"),1,hp,max,veteran,ApparentConcealment.Visible,-1,effects?.OrderBy(x=>x,StringComparer.Ordinal).ToArray()??Array.Empty<string>(),-1,cargo);
  static (GameState S,Unit A,Unit D,ClientInteraction I) Make(LedgerAppearance? a=null,bool genuine=false)
  {
   NativeCombatPreview.Clear();Il2CppSystem.Object.Alias=false;Il2CppSystem.Object.Clones=0;BattleHelpers.Throw=false;BattleHelpers.During=null;BattleHelpers.Enable=true;BattleHelpers.Calls=0;BattleHelpers.FogRetaliation=true;GameManager.Viewing=true;
   var s=new GameState();foreach(UnitType t in Enum.GetValues(typeof(UnitType)))s.Data[t.ToString()]=new(){type=t,health=100,Attack=20,Defence=20,Range=1};
   s.Data["defender"].Defence=30;s.Data["defender"].health=150;s.Data["archer"].Range=2;s.Data["catapult"].Range=3;s.Data["catapult"].NoRetaliate=true;s.Data["firedragon"].health=200;s.Data["firedragon"].Attack=40;s.Data["firedragon"].Range=3;s.Data["dcp_mimic_form_warrior"].health=10;s.Data["dcp_mimic_form_warrior"].Attack=0;s.Data["dcp_mimic_form_warrior"].Defence=10;s.Data["dcp_mimic"].health=10;s.Data["dcp_mimic"].Attack=0;s.Data["dcp_mimic"].NoRetaliate=true;
   var actual=genuine?UnitType.warrior:UnitType.dcp_mimic_form_warrior;
   var attacker=new UnitState{id=1,owner=1,type=UnitType.warrior,UnitData=s.Data["warrior"],health=100,coordinates=new(0,0)};
   var target=new UnitState{id=2,owner=2,type=actual,UnitData=s.Data[actual.ToString()],health=(ushort)(genuine?100:10),coordinates=new(1,0)};
   s.Units.Add(1,attacker);s.Units.Add(2,target);s.Rows[2]=new(2,2,true,genuine?LedgerActualKind.Genuine:LedgerActualKind.Mimic,true,a??Appearance(),PaidInvestmentKind.Known,3);
   var au=new Unit{UnitState=attacker};var du=new Unit{UnitState=target};var map=new MapRenderer();map.Units[1]=au;map.Units[2]=du;MapRenderer.Current=map;GameManager.GameState=s;GameManager.LocalPlayer=new();GameManager.Client=new(){GameState=s};return(s,au,du,new(){selectedUnit=au});
  }
  static string Seal(GameState s)=>string.Join("|",s.Units.Values.OrderBy(u=>u.id).Select(u=>$"{u.Pointer}/{u.id}/{u.owner}/{u.type}/{u.health}/{u.promotionLevel}/{u.moved}/{u.attacked}/{u.UnitData.Pointer}/{u.UnitData.health}/{u.UnitData.Attack}/{u.UnitData.Defence}/{string.Join(',',u.effects)}/{u.passengerUnit?.Pointer}/{u.passengerUnit?.health}"))+":"+string.Join("|",s.Data.Values.Select(d=>$"{d.Pointer}/{d.health}/{d.Defence}/{d.Attack}"));
  static BattleResults Actual(GameState s,Unit a,Unit d)=>BattleHelpers.GetBattleResults(s,a.UnitState,d.UnitState,true,false);
  static void Throws(Action a){bool caught=false;try{a();}catch(InvalidOperationException){caught=true;}Check(caught,"exception preserved");}
  public static int Run(){try{Console.WriteLine(RunCore());return 0;}catch(Exception e){Console.WriteLine(JsonSerializer.Serialize(new{status="FAIL",completed=Tests.Count,assertions=Assertions,error=e.ToString()}));return 1;}}
  static string RunCore()
  {
   Test("PREVIEW-001 audited safe registrations",()=>{var h=new HarmonyLib.Harmony();NativeCombatPreview.Install(h);Check(h.Patched.Count==9,"nine exact hooks");Check(typeof(BattleResults).IsValueType&&typeof(BattleResults).BaseType==typeof(ValueType),"true CLR result, not native ValueType wrapper");});
   Test("PREVIEW-047 Rogue source friendly hover owner gate",()=>{var(s,a,d,i)=Make(genuine:true);d.UnitState.owner=1;s.Rows[1]=new(1,1,true,LedgerActualKind.Genuine,false,null,PaidInvestmentKind.Known,3){Rogue=new(2,1,3)};i.OwnerGate=true;var before=Seal(s);i.StartHoverUnit(d);Check(i.Indicator.Shown&&i.Last.attackDamage>0,"Rogue to friendly reaches native calculator");Check(before==Seal(s)&&Native.Same(a.Owner,d.Owner),"real owners and all combat state unchanged after hover");});
   Test("PREVIEW-048 ordinary friendly hover stays suppressed",()=>{var(s,a,d,i)=Make(genuine:true);d.UnitState.owner=1;i.OwnerGate=true;i.StartHoverUnit(d);Check(!i.Indicator.Shown&&BattleHelpers.Calls==0,"ordinary allies retain native early exit");});
   Test("PREVIEW-049 Rogue owner exception consumed once",()=>{var(s,a,d,i)=Make(genuine:true);d.UnitState.owner=1;s.Rows[1]=new(1,1,true,LedgerActualKind.Genuine,false,null,PaidInvestmentKind.Known,3){Rogue=new(2,1,3)};NativeCombatPreview.BeforeHover(i,d,out var scope);try{var owner=a.Owner;Check(!Native.Same(owner,d.Owner),"comparison gets detached identity");Check(Native.Same(owner,d.Owner),"later owner queries are authoritative");}finally{NativeCombatPreview.Finished(null,scope);}Check(Native.Same(a.Owner,d.Owner),"scope restored");});
   foreach(string mode in new[]{"reverse","both","enemy"})Test("PREVIEW-050 Rogue hover direction "+mode,()=>{var(s,a,d,i)=Make(genuine:true);if(mode!="enemy")d.UnitState.owner=1;if(mode!="reverse")s.Rows[1]=new(1,1,true,LedgerActualKind.Genuine,false,null,PaidInvestmentKind.Known,3){Rogue=new(2,1,3)};if(mode!="enemy")s.Rows[2]=s.Rows[2] with{Rogue=new(2,1,3)};var before=Seal(s);i.StartHoverUnit(d);Check(i.Indicator.Shown&&i.Last.attackDamage>0,"legal direction calculated");Check(before==Seal(s),"no real state mutation");});
   foreach(string guard in new[]{"hidden","replay","viewer","stale","closed"})Test("PREVIEW-051 Rogue hover guard "+guard,()=>{var(s,a,d,i)=Make(genuine:true);d.UnitState.owner=1;s.Rows[1]=new(1,1,true,LedgerActualKind.Genuine,false,null,PaidInvestmentKind.Known,3){Rogue=new(2,1,3)};NativeCombatPreview.BeforeHover(i,d,out var scope);try{if(guard=="hidden")d.Invisible=true;if(guard=="replay")GameManager.Client!.IsReplay=true;if(guard=="viewer")GameManager.LocalPlayer!.Id=2;if(guard=="stale")s.CurrentTurn++;if(guard=="closed")NativeCombatPreview.Finished(null,scope);Check(Native.Same(a.Owner,d.Owner),"guard preserves real owner equality");}finally{NativeCombatPreview.Finished(null,scope);}});
   Test("PREVIEW-002 old native secrecy regression",()=>{var(s,a,d,i)=Make();BattleHelpers.Enable=false;i.StartHoverUnit(d);a.UpdateOverlays();Check(i.Last.retaliationDamage==0&&d.Death,"old path leaks no retaliation and 1HP lethal");BattleHelpers.Enable=true;i.StartHoverUnit(d);a.UpdateOverlays();Check(i.Last.retaliationDamage>0&&!d.Death,"apparent defender counters and survives");});
   Test("PREVIEW-003 target-only clone and no live mutation",()=>{var(s,a,d,i)=Make();d.UnitState.moved=true;d.UnitState.attacked=true;var before=Seal(s);i.StartHoverUnit(d);Check(ReferenceEquals(BattleHelpers.SeenAttacker,a.UnitState),"owned attacker remains actual");Check(!ReferenceEquals(BattleHelpers.SeenDefender,d.UnitState)&&BattleHelpers.SeenDefender!.Pointer!=d.UnitState.Pointer,"detached native pointer");Check(BattleHelpers.SeenDefender.UnitData.Pointer!=s.Data["defender"].Pointer,"detached data");Check(before==Seal(s),"all actual fields and registry data unchanged");Check(i.TargetHealth==150&&i.ActorHealth==100&&d.Health==10,"hover HP scoped and removed after return");});
   Test("PREVIEW-004 actual combat outside UI unchanged",()=>{var(s,a,d,i)=Make();var before=Actual(s,a,d);i.StartHoverUnit(d);var after=Actual(s,a,d);Check(before.attackDamage==after.attackDamage&&after.retaliationDamage==0,"real battle stays actual");Check(ReferenceEquals(BattleHelpers.SeenDefender,d.UnitState),"original body supplied");});
   Test("PREVIEW-005 simpleData false barrier during UI",()=>{var(s,a,d,i)=Make();NativeCombatPreview.BeforeHover(i,d,out var scope);var actual=Actual(s,a,d);NativeCombatPreview.Finished(null,scope);Check(actual.retaliationDamage==0&&ReferenceEquals(BattleHelpers.SeenDefender,d.UnitState),"real-mode call not projected even in UI frame");});
   Test("PREVIEW-006 apparent lethal missing from raw HP is restored",()=>{var(s,a,d,i)=Make(Appearance("defender",20,150),true);a.UpdateOverlays();Check(d.Death&&a.overlayUnits.Count==1,"false20HP lethal despite actual100HP");a.ClearUnitOverlays();Check(!d.Death&&a.overlayUnits.Count==0,"native cleanup owns added marker");});
   Test("PREVIEW-007 false native lethal suppressed before show",()=>{var(s,a,d,i)=Make();a.UpdateOverlays();Check(!d.Death&&d.Shows==0&&a.overlayUnits.Count==0,"no real1HP sweat even transiently");});
   Test("PREVIEW-008 genuine same-type false HP",()=>{var(s,a,d,i)=Make(Appearance("warrior",30,100),true);i.StartHoverUnit(d);a.UpdateOverlays();Check(i.TargetHealth==30&&d.Death,"same-type independent HP applies");Check(d.UnitState.health==100,"real HP retained");});
   Test("PREVIEW-009 apparent1HP is intentionally lethal",()=>{var(s,a,d,i)=Make(Appearance("dcp_mimic",10,10),true);i.StartHoverUnit(d);a.UpdateOverlays();Check(i.TargetHealth==10&&i.Last.retaliationDamage==0&&d.Death,"copied exposed Mimic capabilities");});
   Test("PREVIEW-010 apparent veteran max exact once",()=>{var(s,a,d,i)=Make(Appearance("defender",100,200,true));i.StartHoverUnit(d);Check(i.Last.retaliationDamage==10,"false100/200 fraction, no double veteran maximum");Check(BattleHelpers.SeenDefender!.promotionLevel==1,"veteran metadata retained on clone");});
   Test("PREVIEW-011 apparent effects not actual effects",()=>{var(s,a,d,i)=Make(Appearance(effects:new[]{"Poisoned","Boosted"}));d.UnitState.effects.Add(UnitEffect.Frozen);var before=Seal(s);i.StartHoverUnit(d);Check(i.Last.attackDamage==90&&i.Last.retaliationDamage==40,"false poison defence and boosted response: "+i.Last.attackDamage+"/"+i.Last.retaliationDamage);Check(!ReferenceEquals(BattleHelpers.SeenDefender!.effects,d.UnitState.effects)&&!BattleHelpers.SeenDefender.effects.Contains(UnitEffect.Frozen),"effect list detached, truth omitted");Check(before==Seal(s),"source effects intact");});
   Test("PREVIEW-012 independent apparent cargo",()=>{var cargo=Appearance("firedragon",150,200);var(s,a,d,i)=Make(Appearance("transportship",90,150,cargo:cargo));d.UnitState.passengerUnit=new(){id=10,owner=2,health=10,type=UnitType.dcp_mimic,UnitData=s.Data["dcp_mimic"]};var before=Seal(s);i.StartHoverUnit(d);var display=BattleHelpers.SeenDefender!;Check(display.passengerUnit!.type==UnitType.firedragon&&display.passengerUnit.health==150,"cargo apparent profile");Check(display.passengerUnit.Pointer!=d.UnitState.passengerUnit.Pointer&&display.passengerUnit.UnitData.Pointer!=s.Data["firedragon"].Pointer,"cargo/data detached");Check(i.Last.retaliationDamage==12,"hull false maximum rather than real cargo");Check(before==Seal(s),"cargo unchanged");});
   foreach(var form in new[]{"warrior","archer","catapult","firedragon"})Test("PREVIEW-013 retaliation range and ability "+form,()=>{var(s,a,d,i)=Make(Appearance(form,150,200));d.UnitState.coordinates=new(2,0);i.StartHoverUnit(d);Check((i.Last.retaliationDamage>0)==(form is "archer" or "firedragon"),"native apparent range and no-retaliation");});
   Test("PREVIEW-014 actual focused own disguised attacker",()=>{var(s,a,d,i)=Make();a.UnitState.UnitData=s.Data["archer"];a.UnitState.type=UnitType.archer;a.UnitState.health=40;s.Rows[1]=new(1,1,true,LedgerActualKind.Genuine,true,Appearance("firedragon",200,200),PaidInvestmentKind.Known,3);a.ActualFocus=true;i.StartHoverUnit(d);Check(ReferenceEquals(BattleHelpers.SeenAttacker,a.UnitState)&&i.ActorHealth==40,"own false dragon never enters calculator");});
   Test("PREVIEW-015 remembered Rogue target truth",()=>{var(s,a,d,i)=Make();s.Rows[2]=s.Rows[2] with{Rogue=new(1,2,2)};d.ActualFocus=true;i.StartHoverUnit(d);a.UpdateOverlays();Check(ReferenceEquals(BattleHelpers.SeenDefender,d.UnitState)&&i.TargetHealth==10&&d.Death,"permanent owner entitled actual");});
   Test("PREVIEW-016 another viewer's Rogue stays apparent",()=>{var(s,a,d,i)=Make();s.Rows[2]=s.Rows[2] with{Rogue=new(3,2,2)};i.StartHoverUnit(d);Check(i.TargetHealth==150&&i.Last.retaliationDamage>0,"remembered ownership not global reveal");});
   foreach(string invalid in new[]{"replay","spectator","not-viewing","stale-client-state","stale-map-unit","dead-actor","hidden-actor","invisible-actor"})Test("PREVIEW-017 guard "+invalid,()=>{var(s,a,d,i)=Make();switch(invalid){case "not-ready":s.Ready=false;break;case "replay":GameManager.Client!.IsReplay=true;break;case "spectator":GameManager.Client!.IsSpectating=true;break;case "waiting":GameManager.Client!.IsWaitingForCommand=true;break;case "processing":GameManager.Client!.ActionManager.IsProcessing=true;break;case "foreign-current":s.CurrentPlayer=2;break;case "foreign-owner":a.UnitState.owner=2;break;case "not-viewing":GameManager.Viewing=false;break;case "stale-client-state":GameManager.Client!.GameState=new();break;case "stale-map-unit":MapRenderer.Current!.Units[1]=new(){UnitState=a.UnitState};break;case "dead-actor":a.UnitState.health=0;break;case "hidden-actor":a.Visible=false;break;case "invisible-actor":a.Invisible=true;break;}i.StartHoverUnit(d);Check(ReferenceEquals(BattleHelpers.SeenDefender,d.UnitState)&&Il2CppSystem.Object.Clones==0,"unsupported UI does not project");});
   foreach(string invalid in new[]{"hidden","invisible","dead","foreign-map","foreign-state","not-independent"})Test("PREVIEW-018 target guard "+invalid,()=>{var(s,a,d,i)=Make();switch(invalid){case "hidden":d.Visible=false;break;case "invisible":d.Invisible=true;break;case "dead":d.UnitState.health=0;break;case "foreign-map":MapRenderer.Current!.Units[2]=new(){UnitState=d.UnitState};break;case "foreign-state":s.Units[2]=new(){id=2};break;case "no-row":s.Rows.Clear();break;case "dead-row":s.Rows[2]=s.Rows[2] with{Alive=false,Independent=false,Appearance=null};break;case "not-independent":s.Rows[2]=s.Rows[2] with{Kind=LedgerActualKind.Genuine,Independent=false,Appearance=null};d.UnitState.type=UnitType.warrior;d.UnitState.UnitData=s.Data["warrior"];d.UnitState.health=100;break;}i.StartHoverUnit(d);Check(ReferenceEquals(BattleHelpers.SeenDefender,d.UnitState)&&Il2CppSystem.Object.Clones==0,"inaccessible or stale target not projected");});
   Test("PREVIEW-019 hidden fog veto retained",()=>{var(s,a,d,i)=Make();BattleHelpers.FogRetaliation=false;i.StartHoverUnit(d);Check(i.Last.retaliationDamage==0,"native visibility remains authoritative");});
   Test("PREVIEW-020 native calculator exception cleanup",()=>{var(s,a,d,i)=Make();BattleHelpers.Throw=true;Throws(()=>i.StartHoverUnit(d));BattleHelpers.Throw=false;Check(d.Health==10&&Actual(s,a,d).retaliationDamage==0,"all scopes restored on native exception");});
   Test("PREVIEW-021 overlay exception cleanup",()=>{var(s,a,d,i)=Make();a.ThrowOverlay=true;Throws(()=>a.UpdateOverlays());Check(Actual(s,a,d).retaliationDamage==0&&d.Health==10,"overlay failure restores scope");});
   Test("PREVIEW-022 clear invalidates pending scope",()=>{var(s,a,d,i)=Make();NativeCombatPreview.BeforeHover(i,d,out var scope);NativeCombatPreview.Clear();NativeCombatPreview.Finished(null,scope);i.DuringHover=()=>NativeCombatPreview.Clear();i.StartHoverUnit(d);Check(ReferenceEquals(BattleHelpers.SeenDefender,d.UnitState),"old finalizer cannot revive context");});
   Test("PREVIEW-023 nested rejected UI cannot inherit outer",()=>{var(s,a,d,i)=Make();NativeCombatPreview.BeforeHover(i,d,out var outer);NativeCombatPreview.BeforeHover(new ClientInteraction(),d,out var inner);BattleHelpers.GetBattleResults(s,a.UnitState,d.UnitState,true,true);Check(ReferenceEquals(BattleHelpers.SeenDefender,d.UnitState),"invalid nested fence");NativeCombatPreview.Finished(null,inner);i.StartHoverUnit(d);Check(i.TargetHealth==150,"outer remains usable");NativeCombatPreview.Finished(null,outer);});
   Test("PREVIEW-024 clone alias rejected before scalar write",()=>{var(s,a,d,i)=Make();var before=Seal(s);Il2CppSystem.Object.Alias=true;i.StartHoverUnit(d);Check(!i.Indicator.Shown&&i.Last.attackDamage==0,"failed projection hides prediction rather than using hidden facts");Check(before==Seal(s),"failed native clone never writes source");Il2CppSystem.Object.Alias=false;Check(Actual(s,a,d).retaliationDamage==0,"alias failure restores scope");});
   Test("PREVIEW-025 retained Rogue sight bridge only exact clone",()=>{var(s,a,d,i)=Make();object? bridge=null,other=null;BattleHelpers.During=()=>{bridge=NativeCombatPreview.ActualBody(s,BattleHelpers.SeenDefender!);other=NativeCombatPreview.ActualBody(new GameState(),BattleHelpers.SeenDefender!);};i.StartHoverUnit(d);Check(ReferenceEquals(bridge,d.UnitState)&&ReferenceEquals(other,BattleHelpers.SeenDefender),"only same-state active clone resolves truth for sight binding");Check(ReferenceEquals(NativeCombatPreview.ActualBody(s,BattleHelpers.SeenDefender!),BattleHelpers.SeenDefender),"closed calculation no bridge");});
   Test("PREVIEW-026 repeated calculation caches bounded target clone",()=>{var(s,a,d,i)=Make();NativeCombatPreview.BeforeHover(i,d,out var scope);BattleHelpers.GetBattleResults(s,a.UnitState,d.UnitState,true,true);int n=Il2CppSystem.Object.Clones;BattleHelpers.GetBattleResults(s,a.UnitState,d.UnitState,true,true);Check(Il2CppSystem.Object.Clones==n,"no second allocation within one UI query");NativeCombatPreview.Finished(null,scope);});
   Test("PREVIEW-027 stale immutable row cannot retain false profile",()=>{var(s,a,d,i)=Make();NativeCombatPreview.BeforeHover(i,d,out var scope);BattleHelpers.GetBattleResults(s,a.UnitState,d.UnitState,true,true);s.Rows[2]=s.Rows[2] with{Appearance=Appearance("warrior",100,100)};Check(d.Health==10,"cached row invalidated before HP use");NativeCombatPreview.AfterOverlays(true,scope);NativeCombatPreview.Finished(null,scope);});
   foreach(string mutation in new[]{"map","client","viewer","turn","body","selection"})Test("PREVIEW-028 callback context changes "+mutation,()=>{var(s,a,d,i)=Make();i.DuringHover=()=>{switch(mutation){case "map":s.Map=new();break;case "client":GameManager.Client=new(){GameState=s};break;case "viewer":GameManager.LocalPlayer!.Id=2;break;case "turn":s.CurrentTurn++;break;case "body":a.UnitState=new(){id=1};break;case "selection":i.selectedUnit=d;break;}};i.StartHoverUnit(d);Check(Il2CppSystem.Object.Clones==0&&!i.Indicator.Shown,"changed context suppresses stale indicators without allocating a projection");});
   Test("PREVIEW-029 production snapshot returns independent rows",()=>{var(s,a,d,i)=Make();var one=NativeRegroupSession.ReadIdentity(s,2)!;var two=NativeRegroupSession.ReadIdentity(s,2)!;Check(!ReferenceEquals(one,two)&&!ReferenceEquals(one.Appearance!.Effects,two.Appearance!.Effects),"real production reader copies rows/effects");i.StartHoverUnit(d);a.UpdateOverlays();Check(i.TargetHealth==150&&!d.Death,"snapshot binding works despite fresh rows");});
   Test("PREVIEW-030 failed appearance lookup is contained and hidden",()=>{var(s,a,d,i)=Make();s.Data.Remove("defender");int old=Entry.Errors;i.StartHoverUnit(d);Check(!i.Indicator.Shown&&i.Last.attackDamage==0&&d.UnitState.health==10,"no actual-stat fallback");i.StartHoverUnit(d);Check(Entry.Errors==old+1,"one bounded diagnostic for repeated display failure");});
   Test("PREVIEW-031 apparent owned attacker follows map focus",()=>{var(s,a,d,i)=Make();a.UnitState.type=UnitType.archer;a.UnitState.UnitData=s.Data["archer"];a.UnitState.health=40;s.Rows[1]=new(1,1,true,LedgerActualKind.Genuine,true,Appearance("firedragon",200,200),PaidInvestmentKind.Known,3);var before=Seal(s);i.StartHoverUnit(d);Check(BattleHelpers.SeenAttacker!.type==UnitType.firedragon&&i.ActorHealth==200,"apparent source supplied before calculation");int masked=i.Last.attackDamage;a.ActualFocus=true;i.StartHoverUnit(d);Check(ReferenceEquals(BattleHelpers.SeenAttacker,a.UnitState)&&i.ActorHealth==40&&i.Last.attackDamage<masked,"actual focus changes source only");Check(before==Seal(s),"no true stats or flags written");});
   Test("PREVIEW-032 enemy Mimic attacker is never zero-stat source",()=>{var(s,a,d,i)=Make();i.selectedUnit=d;var before=Seal(s);i.StartHoverUnit(a);Check(i.Last.attackDamage>0&&BattleHelpers.SeenAttacker!.type==UnitType.defender,"enemy apparent source has represented attack");Check(i.ActorHealth==150&&i.TargetHealth==100,"both roles use displayed HP");Check(Actual(s,d,a).attackDamage==0&&before==Seal(s),"real Mimic attack remains zero");});
   foreach(bool actual in new[]{false,true})Test("PREVIEW-033 own disguised defender focus "+actual,()=>{var(s,a,d,i)=Make();a.UnitState.type=UnitType.dcp_mimic_form_warrior;a.UnitState.UnitData=s.Data["dcp_mimic_form_warrior"];a.UnitState.health=10;s.Rows[1]=new(1,1,true,LedgerActualKind.Mimic,true,Appearance(),PaidInvestmentKind.Known,3);a.ActualFocus=actual;i.selectedUnit=d;i.StartHoverUnit(a);Check(i.TargetHealth==(actual?10:150)&&i.ActorHealth==150,"owner target focus and enemy source appearance independent");Check((i.Last.retaliationDamage==0)==actual,"apparent defender retaliation follows represented form");});
   Test("PREVIEW-034 remembered Rogue follows map focus",()=>{var(s,a,d,i)=Make();s.Rows[2]=s.Rows[2] with{Rogue=new(1,2,2)};i.StartHoverUnit(d);Check(i.TargetHealth==150,"remembered truth entitlement does not force actual view");d.ActualFocus=true;i.StartHoverUnit(d);Check(i.TargetHealth==10,"explicit remembered-owner actual focus applies");});
   foreach(string phase in new[]{"waiting","processing","both"})Test("PREVIEW-035 first busy frame projected "+phase,()=>{var(s,a,d,i)=Make();GameManager.Client!.IsWaitingForCommand=phase!="processing";GameManager.Client.ActionManager.IsProcessing=phase!="waiting";i.StartHoverUnit(d);a.UpdateOverlays();Check(i.Indicator.Writes.Count==1&&i.Indicator.Writes[0].Health==150,"first native damage write uses apparent HP");Check(d.Shows==0&&!d.Death&&i.Last.retaliationDamage>0,"no temporary actual1HP sweat or zero retaliation");Check(Actual(s,a,d).retaliationDamage==0,"busy true combat still untouched");});
   Test("PREVIEW-036 first tile danger uses displayed attacker HP",()=>{var(s,a,d,i)=Make();a.UnitState.type=UnitType.dcp_mimic_form_warrior;a.UnitState.UnitData=s.Data["dcp_mimic_form_warrior"];a.UnitState.health=10;s.Rows[1]=new(1,1,true,LedgerActualKind.Mimic,true,Appearance("firedragon",200,200),PaidInvestmentKind.Known,3);a.UpdateOverlays();Check(a.LastOwnLethal,"native inline raw HP really chose lethal");Check(d.Tile.Writes.Count==1&&d.Tile.Writes[0]==OverlayType.Attack,"first actual tile write corrected before rendering");Check(a.UnitState.health==10,"real1HP retained");});
   Test("PREVIEW-037 false HP lethal exists before native overlay sink",()=>{var(s,a,d,i)=Make(Appearance("defender",20,150),true);bool beforeSink=false;d.Tile.BeforeWrite=()=>beforeSink=d.Death;a.UpdateOverlays();Check(beforeSink&&d.Shows==1&&d.Death,"marker created from native prediction before first tile sink; no postfix visual repair");});
   Test("PREVIEW-038 both sides apparent independent effects and maxima",()=>{var(s,a,d,i)=Make(Appearance(effects:new[]{"Poisoned"}));s.Rows[1]=new(1,1,true,LedgerActualKind.Genuine,true,Appearance("firedragon",100,250,true,new[]{"Boosted"}),PaidInvestmentKind.Known,3);var before=Seal(s);i.StartHoverUnit(d);Check(BattleHelpers.SeenAttacker!.health==100&&BattleHelpers.SeenAttacker.promotionLevel==1&&BattleHelpers.SeenAttacker.effects.Contains(UnitEffect.Boosted),"source snapshot projected");Check(i.Last.attackDamage==86,"source maximum250 applied exactly once with native fixture formula");Check(before==Seal(s),"both actual effect lists and registry remain intact");});
   Test("PREVIEW-039 source cargo is detached too",()=>{var(s,a,d,i)=Make();s.Rows[1]=new(1,1,true,LedgerActualKind.Genuine,true,Appearance("transportship",80,120,cargo:Appearance("archer",30,100)),PaidInvestmentKind.Known,3);i.StartHoverUnit(d);Check(BattleHelpers.SeenAttacker!.passengerUnit!.type==UnitType.archer&&a.UnitState.passengerUnit is null,"only detached apparent source cargo created");});
   Test("PREVIEW-040 same-owner Rogue target still projected",()=>{var(s,a,d,i)=Make();d.UnitState.owner=1;s.Rows[2]=s.Rows[2] with{Rogue=new(3,1,3)};i.StartHoverUnit(d);Check(i.TargetHealth==150,"native allegiance exception does not remove apparent profile");});
   Test("PREVIEW-041 unavailable binding cannot show actual secrecy",()=>{var(s,a,d,i)=Make();s.Ready=false;i.StartHoverUnit(d);a.UpdateOverlays();Check(!i.Indicator.Shown&&!i.OwnIndicator.Shown&&d.Shows==0,"no first writes from unavailable snapshot");Check(Il2CppSystem.Object.Clones==0,"no unauthorized projection");});
   foreach(bool dead in new[]{false,true})Test("PREVIEW-042 missing or stale Mimic identity fails closed "+dead,()=>{var(s,a,d,i)=Make();if(dead)s.Rows[2]=s.Rows[2] with{Alive=false,Independent=false,Appearance=null};else s.Rows.Clear();i.StartHoverUnit(d);a.UpdateOverlays();Check(!i.Indicator.Shown&&d.Shows==0,"unbound carrier never substitutes true1HP");});
   Test("PREVIEW-043 focus changed during calculator hides prediction",()=>{var(s,a,d,i)=Make();s.Rows[1]=new(1,1,true,LedgerActualKind.Genuine,true,Appearance("firedragon",200,200),PaidInvestmentKind.Known,3);BattleHelpers.During=()=>a.ActualFocus=true;i.StartHoverUnit(d);Check(!i.Indicator.Shown&&!i.OwnIndicator.Shown,"obsolete mixed-mode result hidden");});
   Test("PREVIEW-044 ordinary target following apparent clears old pair",()=>{var(s,a,d,i)=Make();NativeCombatPreview.BeforeOverlays(a,out var scope);BattleHelpers.GetBattleResults(s,a.UnitState,d.UnitState,true,true);var other=new UnitState{id=3,owner=2,health=100,UnitData=s.Data["warrior"]};var u=new Unit{UnitState=other};s.Units[3]=other;MapRenderer.Current!.Units[3]=u;BattleHelpers.GetBattleResults(s,a.UnitState,other,true,true);var tile=new Tile{Unit=u};tile.ShowOverlay(OverlayType.Kill);Check(tile.Writes[0]==OverlayType.Kill,"previous target cannot rewrite unrelated later sink");NativeCombatPreview.Finished(null,scope);});
   Test("PREVIEW-045 displayed source bridge for Rogue sight",()=>{var(s,a,d,i)=Make();s.Rows[1]=new(1,1,true,LedgerActualKind.Genuine,true,Appearance("firedragon",200,200),PaidInvestmentKind.Known,3);object? actual=null;BattleHelpers.During=()=>actual=NativeCombatPreview.ActualBody(s,BattleHelpers.SeenAttacker!);i.StartHoverUnit(d);Check(ReferenceEquals(actual,a.UnitState),"only sight identity gets actual source bridge");});
   Test("PREVIEW-046 native waiting opponent turn hover remains private",()=>{var(s,a,d,i)=Make();s.CurrentPlayer=2;i.selectedUnit=d;i.StartHoverUnit(a);Check(i.ActorHealth==150&&i.Last.attackDamage>0,"viewer can inspect enemy source while waiting");});
   Test("PREVIEW-047 native overlay availability remains own turn",()=>{var(s,a,d,i)=Make();NativeCombatPreview.BeforeOverlays(d,out var scope);Check(scope is not null&&!scope.Bound,"no enemy command overlay grant");NativeCombatPreview.Finished(null,scope);s.CurrentPlayer=2;NativeCombatPreview.BeforeOverlays(a,out scope);Check(scope is not null&&!scope.Bound,"no out-of-turn command overlay grant");NativeCombatPreview.Finished(null,scope);});
   Test("PREVIEW-048 attack tile enums outside exact pair unchanged",()=>{var(s,a,d,i)=Make();NativeCombatPreview.BeforeOverlays(a,out var scope);BattleHelpers.GetBattleResults(s,a.UnitState,d.UnitState,true,true);var tile=new Tile{Unit=a};tile.ShowOverlay(OverlayType.Kill);d.Tile.Unit=d;d.Tile.ShowOverlay(OverlayType.Walk);Check(tile.Writes[0]==OverlayType.Kill&&d.Tile.Writes[0]==OverlayType.Walk,"unrelated native tile types unaffected");NativeCombatPreview.Finished(null,scope);});
   Test("PREVIEW-049 sweat refuses before matching calculation",()=>{var(s,a,d,i)=Make();NativeCombatPreview.BeforeOverlays(a,out var scope);d.ShowDeathIndicator();UnitState actor=a.UnitState,target=d.UnitState;BattleResults result=default;NativeCombatPreview.BeforeBattle(s,ref actor,ref target,true,ref result,out var calculation);d.ShowDeathIndicator();NativeCombatPreview.AfterBattle(new BattleResults{attackDamage=60,retaliationDamage=20},calculation);d.ShowDeathIndicator();Check(d.DeathAttempts.Count==3&&d.DeathAttempts.All(x=>!x)&&d.Shows==0,"all attempted native writes refused; no after-the-fact hide");NativeCombatPreview.BattleFinished(null,calculation);NativeCombatPreview.Finished(null,scope);});
   Test("PREVIEW-050 apparent attacker low health makes first tile lethal",()=>{var(s,a,d,i)=Make();s.Rows[1]=new(1,1,true,LedgerActualKind.Genuine,true,Appearance("warrior",10,100),PaidInvestmentKind.Known,3);a.UpdateOverlays();Check(!a.LastOwnLethal&&d.Tile.Writes.Single()==OverlayType.Kill,"native truth survived but first displayed sink uses apparent10HP");});
   Test("PREVIEW-051 no prediction cannot publish guessed indicators",()=>{var(s,a,d,i)=Make();NativeCombatPreview.BeforeHover(i,d,out var scope);i.Indicator.Show(d,10,10,0);Check(!i.Indicator.Shown,"before calculator no true-health indicator fallback");NativeCombatPreview.Finished(null,scope);NativeCombatPreview.BeforeOverlays(a,out scope);d.Tile.Unit=d;d.Tile.ShowOverlay(OverlayType.Kill);Check(d.Tile.Writes.Count==0,"before calculator no true-danger tile fallback");NativeCombatPreview.Finished(null,scope);});
   Test("PREVIEW-052 retained native sinks outside UI unchanged",()=>{var(s,a,d,i)=Make();d.ShowDeathIndicator();d.Tile.Unit=d;d.Tile.ShowOverlay(OverlayType.Kill);i.Indicator.Show(d,10,10,0);Check(d.Shows==1&&d.Tile.Writes.Single()==OverlayType.Kill&&i.Indicator.Writes.Single().Health==10,"no global display or actual HP override");});
